    MSG = _mm_loadu_si128((const __m128i*)(p+32));
    M2 = _mm_shuffle_epi8(MSG, _mm_set_epi8(12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3));
    MSG = _mm_add_epi32(M2, _mm_set_epi32(K[8],K[9],K[10],K[11]));
    TMP = _mm_sha256rnds2_epu32(STATE0, STATE1, MSG);
    MSG = _mm_shuffle_epi32(MSG, 0x0E);
    STATE1 = _mm_sha256rnds2_epu32(STATE1, TMP, MSG);
    STATE0 = TMP;
