      M0 = _mm_sha256msg1_epu32(M0, M1);
      M0 = _mm_add_epi32(M0, _mm_alignr_epi8(M3, M2, 4));
      M0 = _mm_sha256msg2_epu32(M0, M3);
      MSG = _mm_add_epi32(M0, _mm_set_epi32(K[i],K[i+1],K[i+2],K[i+3]));
