      MSG = _mm_shuffle_epi32(MSG, 0x0E);
      STATE1 = _mm_sha256rnds2_epu32(STATE1, TMP, MSG);
      STATE0 = TMP;
      M2 = M3; M3 = M0; M0 = M1; M1 = M2;
    }
    STATE0 = _mm_add_epi32(STATE0, ABEF_SAVE);
    STATE1 = _mm_add_epi32(STATE1, CDGH_SAVE);
    p += 64;
  }
  // extract
  uint32_t tmp[4];
  _mm_storeu_si128((__m128i*)tmp, STATE0);
  state[0]=tmp[3]; state[1]=tmp[2]; state[2]=tmp[1]; state[3]=tmp[0];
